-- TORVO V2 PURCHASE MAKER-CHECKER FINAL BOUNDARY
-- Install after atomic Purchase + central approval foundation.
-- OWNER may save/receive directly. ADMIN submits immutable purchase snapshot; stock changes only after approval.

create or replace function public.submit_purchase_for_approval(p_supplier uuid,p_invoice_no text,p_invoice_date date,p_lines jsonb,p_note text default null,p_request_key text default null)
returns uuid language plpgsql security definer set search_path=public as $$
declare a app_users%rowtype;r uuid;ph text;x jsonb;i uuid;q numeric;rate numeric;total numeric:=0;
begin
 select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role<>'admin'then raise exception 'Admin authorization required';end if;
 if p_supplier is null or not exists(select 1 from suppliers where id=p_supplier and active=true)then raise exception 'Active supplier required';end if;if nullif(trim(p_invoice_no),'')is null or p_invoice_date is null or p_invoice_date>current_date then raise exception 'Valid invoice details required';end if;if nullif(trim(p_request_key),'')is null then raise exception 'Request key required';end if;if jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)=0 then raise exception 'Purchase items required';end if;if exists(select 1 from(select e->>'item_id'i,count(*)c from jsonb_array_elements(p_lines)e group by e->>'item_id')s where i is null or c>1)then raise exception 'Duplicate/missing purchase item';end if;
 for x in select * from jsonb_array_elements(p_lines)loop begin i:=(x->>'item_id')::uuid;q:=(x->>'qty')::numeric;rate:=(x->>'purchase_rate')::numeric;exception when others then raise exception 'Invalid purchase line';end;if q<=0 or rate<0 or not exists(select 1 from catalog_items where id=i and active=true)then raise exception 'Invalid purchase line/item';end if;total:=total+q*rate;end loop;
 if exists(select 1 from purchase_headers where supplier_id=p_supplier and upper(trim(invoice_no))=upper(trim(p_invoice_no)))then raise exception 'Duplicate supplier invoice';end if;
 ph:=md5(jsonb_build_object('supplier',p_supplier,'invoice',upper(trim(p_invoice_no)),'date',p_invoice_date,'lines',p_lines,'note',coalesce(upper(trim(p_note)),''),'request_key',trim(p_request_key))::text);
 select id into r from approval_requests where module='purchase' and entity_type='purchase_entry' and entity_id=trim(p_request_key) and action_type='SAVE_RECEIVE_PURCHASE' and status='pending_approval';if found then if (select payload_snapshot->>'payload_hash' from approval_requests where id=r)=ph then return r;else raise exception 'Request key already submitted with different Purchase data';end if;end if;
 insert into approval_requests(module,entity_type,entity_id,action_type,maker_id,amount_snapshot,summary,payload_snapshot)values('purchase','purchase_entry',trim(p_request_key),'SAVE_RECEIVE_PURCHASE',a.id,total,'PURCHASE · '||upper(trim(p_invoice_no)),jsonb_build_object('supplier_id',p_supplier,'invoice_no',upper(trim(p_invoice_no)),'invoice_date',p_invoice_date,'lines',p_lines,'note',upper(trim(coalesce(p_note,''))),'request_key',trim(p_request_key),'payload_hash',ph))returning id into r;
 insert into approval_history(approval_id,action,actor_id,details)values(r,'submitted',a.id,jsonb_build_object('invoice_no',upper(trim(p_invoice_no)),'amount',total));insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'PURCHASE_APPROVAL_SUBMITTED','approval_request',r::text,jsonb_build_object('invoice_no',upper(trim(p_invoice_no)),'request_key',trim(p_request_key),'amount',total));return r;
end;$$;

create or replace function public.decide_purchase_approval(p_approval uuid,p_decision text,p_note text default null)
returns uuid language plpgsql security definer set search_path=public as $$
declare a app_users%rowtype;r approval_requests%rowtype;perm approval_permissions%rowtype;allowed boolean:=false;pid uuid;p jsonb;
begin
 select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found then raise exception 'Not authorized';end if;select * into r from approval_requests where id=p_approval for update;if not found or r.module<>'purchase'or r.entity_type<>'purchase_entry'or r.action_type<>'SAVE_RECEIVE_PURCHASE'then raise exception 'Purchase approval not found';end if;if r.status<>'pending_approval'then raise exception 'Approval already decided';end if;if lower(trim(p_decision))not in('approved','rejected')then raise exception 'Decision must be APPROVED or REJECTED';end if;
 if a.role='owner'then allowed:=true;elsif a.role in('admin','accountant')then select * into perm from approval_permissions where user_id=a.id;allowed:=found and perm.can_approve_transactions;end if;if not allowed then raise exception 'Approval permission required';end if;if r.maker_id=a.id and a.role<>'owner'and not coalesce(perm.can_approve_own_entry,false)then raise exception 'Self approval is not permitted';end if;
 if lower(trim(p_decision))='rejected'then update approval_requests set status='rejected',checker_id=a.id,checker_note=nullif(upper(trim(coalesce(p_note,''))),''),decided_at=now(),updated_at=now()where id=r.id;insert into approval_history(approval_id,action,actor_id,note)values(r.id,'rejected',a.id,nullif(upper(trim(coalesce(p_note,''))),''));return null;end if;
 p:=r.payload_snapshot;pid:=save_and_receive_purchase_entry((p->>'supplier_id')::uuid,p->>'invoice_no',(p->>'invoice_date')::date,p->'lines',nullif(p->>'note',''),p->>'request_key');update approval_requests set status='approved',checker_id=a.id,checker_note=nullif(upper(trim(coalesce(p_note,''))),''),decided_at=now(),updated_at=now(),payload_snapshot=payload_snapshot||jsonb_build_object('purchase_id',pid,'effect_applied_at',now())where id=r.id;insert into approval_history(approval_id,action,actor_id,note,details)values(r.id,'approved',a.id,nullif(upper(trim(coalesce(p_note,''))),''),jsonb_build_object('purchase_id',pid));insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'PURCHASE_APPROVAL_APPLIED','approval_request',r.id::text,jsonb_build_object('purchase_id',pid));return pid;
end;$$;

-- Final browser boundary: only OWNER can call direct atomic save/receive.
create or replace function public.save_and_receive_purchase_entry(p_supplier uuid,p_invoice_no text,p_invoice_date date,p_lines jsonb,p_note text default null,p_request_key text default null)
returns uuid language plpgsql security definer set search_path=public as $$
declare a app_users%rowtype;h uuid;x jsonb;iid uuid;q numeric;rate numeric;total numeric:=0;ph text;old purchase_save_requests%rowtype;l record;
begin
 select * into a from app_users where auth_user_id=auth.uid() and active=true;if not found or a.role<>'owner'then raise exception 'Owner direct Purchase only; Admin must submit approval';end if;
 if nullif(trim(p_request_key),'')is null then raise exception 'Save request key required';end if;if p_supplier is null or not exists(select 1 from suppliers where id=p_supplier and active=true)then raise exception 'Active supplier required';end if;if nullif(trim(p_invoice_no),'')is null or p_invoice_date is null or p_invoice_date>current_date then raise exception 'Valid invoice details required';end if;if jsonb_typeof(p_lines)<>'array'or jsonb_array_length(p_lines)=0 then raise exception 'Purchase items required';end if;ph:=md5(jsonb_build_object('supplier',p_supplier,'invoice',upper(trim(p_invoice_no)),'date',p_invoice_date,'lines',p_lines,'note',coalesce(trim(p_note),''))::text);select * into old from purchase_save_requests where request_key=trim(p_request_key)for update;if found then if old.payload_hash=ph then return old.purchase_id;else raise exception 'Save request key already used with different Purchase data';end if;end if;if exists(select 1 from(select e->>'item_id'i,count(*)c from jsonb_array_elements(p_lines)e group by e->>'item_id')s where i is null or c>1)then raise exception 'Duplicate/missing purchase item';end if;if exists(select 1 from purchase_headers where supplier_id=p_supplier and upper(trim(invoice_no))=upper(trim(p_invoice_no)))then raise exception 'Duplicate supplier invoice';end if;insert into purchase_headers(supplier_id,invoice_no,invoice_date,total_reference_amount,created_by)values(p_supplier,upper(trim(p_invoice_no)),p_invoice_date,0,a.id)returning id into h;for x in select * from jsonb_array_elements(p_lines)loop begin iid:=(x->>'item_id')::uuid;q:=(x->>'qty')::numeric;rate:=(x->>'purchase_rate')::numeric;exception when others then raise exception 'Invalid purchase line';end;if iid is null or q<=0 or rate<0 or not exists(select 1 from catalog_items where id=iid and active=true)then raise exception 'Invalid purchase line/item';end if;insert into purchase_lines(purchase_id,item_id,qty,purchase_rate)values(h,iid,q,rate);total:=total+q*rate;end loop;update purchase_headers set total_reference_amount=total where id=h;for l in select item_id,sum(qty)qty from purchase_lines where purchase_id=h group by item_id order by item_id loop insert into inventory(item_id,current_qty,updated_at)values(l.item_id,l.qty,now())on conflict(item_id)do update set current_qty=inventory.current_qty+excluded.current_qty,updated_at=now();insert into inventory_movements(item_id,qty_change,reason,reference_type,reference_id,created_by)values(l.item_id,l.qty,'PURCHASE STOCK RECEIVED','purchase',h,a.id);end loop;insert into purchase_stock_receipts(purchase_id,request_key,received_by,details)values(h,trim(p_request_key),a.id,jsonb_build_object('invoice_no',upper(trim(p_invoice_no)),'atomic_save_receive',true,'exactly_once',true));insert into purchase_save_requests(request_key,purchase_id,payload_hash,created_by)values(trim(p_request_key),h,ph,a.id);insert into audit_log(actor_id,action,entity_type,entity_id,details)values(a.id,'PURCHASE_SAVED_AND_RECEIVED','purchase',h::text,jsonb_build_object('total_amount',total,'request_key',trim(p_request_key),'atomic',true));return h;end;$$;
revoke all on function public.submit_purchase_for_approval(uuid,text,date,jsonb,text,text),public.decide_purchase_approval(uuid,text,text),public.save_and_receive_purchase_entry(uuid,text,date,jsonb,text,text) from public,anon;grant execute on function public.submit_purchase_for_approval(uuid,text,date,jsonb,text,text),public.decide_purchase_approval(uuid,text,text),public.save_and_receive_purchase_entry(uuid,text,date,jsonb,text,text) to authenticated;
